use std :: collections :: HashMap ; use std :: fs ; use std :: time :: { SystemTime , UNIX_EPOCH } ; impl RepositoryView { fn new (name : String , description : String) -> Self { RepositoryView { name , description , repositories : Vec :: new () , } } fn get_family_distribution (& self) -> HashMap < String , usize > { let mut distribution = HashMap :: new () ; for repo in & self . repositories { * distribution . entry (repo . group_family . clone ()) . or_insert (0) += 1 ; } distribution } fn get_complexity_stats (& self) -> (f64 , f64 , f64) { if self . repositories . is_empty () { return (0.0 , 0.0 , 0.0) ; } let complexities : Vec < f64 > = self . repositories . iter () . map (| r | r . complexity_score) . collect () ; let min = complexities . iter () . fold (f64 :: INFINITY , | a , & b | a . min (b)) ; let max = complexities . iter () . fold (0.0f64 , | a , & b | a . max (b)) ; let avg = complexities . iter () . sum :: < f64 > () / complexities . len () as f64 ; (min , max , avg) } fn generate_atlas_data (& self) -> String { let mut data = String :: new () ; data . push_str (& format ! ("# Repository Mathematical Atlas: {}\n\n" , self . name)) ; data . push_str (& format ! ("**Description**: {}\n\n" , self . description)) ; let family_dist = self . get_family_distribution () ; data . push_str ("## Family Distribution\n\n") ; for (family , count) in family_dist { data . push_str (& format ! ("- **{}**: {} repositories\n" , family , count)) ; } data . push_str ("\n") ; let (min_comp , max_comp , avg_comp) = self . get_complexity_stats () ; data . push_str ("## Complexity Statistics\n\n") ; data . push_str (& format ! ("- **Minimum Complexity**: {:.2}\n" , min_comp)) ; data . push_str (& format ! ("- **Maximum Complexity**: {:.2}\n" , max_comp)) ; data . push_str (& format ! ("- **Average Complexity**: {:.2}\n" , avg_comp)) ; data . push_str ("\n") ; data . push_str ("## Repository Details\n\n") ; for (i , repo) in self . repositories . iter () . enumerate () { data . push_str (& format ! ("### {}. {}\n" , i + 1 , repo . name)) ; data . push_str (& format ! ("- **Path**: {}\n" , repo . path)) ; data . push_str (& format ! ("- **Group Family**: {}\n" , repo . group_family)) ; data . push_str (& format ! ("- **Group Order**: {}\n" , repo . group_order)) ; data . push_str (& format ! ("- **Group Rank**: {}\n" , repo . group_rank)) ; data . push_str (& format ! ("- **Complexity Score**: {:.2}\n" , repo . complexity_score)) ; data . push_str (& format ! ("- **Simple Subgroups**: {}\n" , repo . simple_subgroups . join (", "))) ; data . push_str (& format ! ("- **Stars**: {}\n" , repo . stars)) ; data . push_str (& format ! ("- **Forks**: {}\n" , repo . forks)) ; data . push_str (& format ! ("- **Contributors**: {}\n" , repo . contributors)) ; data . push_str (& format ! ("- **Language**: {}\n" , repo . language)) ; data . push_str (& format ! ("- **Size**: {} MB\n" , repo . size_mb)) ; data . push_str (& format ! ("- **Last Commit**: {} days ago\n" , repo . last_commit_days)) ; data . push_str (& format ! ("- **Tile Size**: {:.0}px\n" , repo . get_tile_size ())) ; data . push_str (& format ! ("- **Tile Color**: {}\n" , repo . get_tile_color ())) ; data . push_str (& format ! ("- **Group Theory Description**: {}\n" , repo . get_group_theory_description ())) ; data . push_str ("\n") ; } data } }